/** Topic lessons have 6–12 screens (05 §2). Checked here too, so the gateway's one repair call
 * asks the model to fix a short lesson instead of it failing verification afterwards. */
export const TOPIC_MIN_SCREENS = 6;
export const lessonGenerateOutput = lessonSpecSchema.refine((l) => l.screens.length >= TOPIC_MIN_SCREENS, {
  message: `A topic lesson needs at least ${TOPIC_MIN_SCREENS} screens. Add screens (keep 1 to 3 blocks each) so there are 6 to 12.`,
  path: ["screens"],
});

export const lessonGenerate = defineSkill({
  name: "lesson_generate",
  inputSchema: lessonGenerateInput,
  outputSchema: lessonGenerateOutput,
  promptVersion: LESSON_BLOCKS_PROMPT_VERSION,
  library: true,
  buildPrompt: (input) => {
    const normalizedProfile = input.subject_profile === "social_science" ? "social" : input.subject_profile;
    const parts: string[] = [
      `Concept: ${input.concept.title}`,
      `Subject: ${input.concept.subject} (use "subject_profile": "${normalizedProfile}" and "dsl_version": 1)`,
    ];
    if (input.concept.description) parts.push(`Description: ${input.concept.description}`);
    if (input.concept.level_band) parts.push(`Level: ${input.concept.level_band}`);
    if (input.concept.prerequisites?.length) parts.push(`Prerequisites: ${input.concept.prerequisites.join(", ")}`);
    if (input.concept.micro_skills?.length) parts.push(`Micro-skills: ${input.concept.micro_skills.join(", ")}`);
    if (input.course_context) {
      parts.push(
        `Course Context: ${input.course_context.code ?? ""} ${input.course_context.title ?? ""} ${
          input.course_context.wording ?? ""
        }`.trim(),
      );
    }

    if (input.outline) {
      parts.push(
        `\nFollow this approved lesson outline:\nObjective: ${input.outline.objective}\nMisconceptions to address: ${input.outline.misconceptions.join(
          "; ",
        )}\nScreens:\n${input.outline.screens
          .map(
            (s, idx) =>
              `  ${idx + 1}. [${s.id}] "${s.title}" (Checkpoint: ${s.is_checkpoint}) - ${
                s.purpose
              }. Planned blocks: ${s.planned_block_types.join(", ")}`,
          )
          .join("\n")}`,
      );
    }

    if (input.chunks.length > 0) {
      parts.push(
        `\n${
          input.sources === "own"
            ? "The student's own course materials (their notes, textbook pages or lab manual). Build the lesson from them: follow their definitions, notation, examples and order, fill gaps with standard university teaching, and cite the ids you draw on in source_refs and source_quote blocks"
            : "Approved Reference Chunks (cite source_chunk_id when quoting)"
        }:\n${input.chunks.map((c) => `<source id="${c.id}">\n${c.content}\n</source>`).join("\n\n")}`,
      );
    } else {
      parts.push(
        "\nNo reference chunks available: explain foundational principles from standard university curriculum.",
      );
    }

    return {
      system: LESSON_BLOCKS_SYSTEM,
      user: parts.join("\n\n"),
    };
  },
});
